 $('art-export').onclick=()=>{const r=lastResult,rows=[['Предмет роскоши',item.name],['ID',item.id],['Сервер',state.server],['Покупка',cfg.buyCity],['Продажа',cfg.sellCity],['Режим количества',cfg.quantityMode==='capacity'?'По грузоподъёмности':'Вручную'],['Грузоподъёмность, кг',cfg.capacity],['Количество',r.quantity],['Цена покупки',cfg.buyPrice||'Нет цены'],['Цена продажи',cfg.sellPrice||'Нет цены'],['Вес, кг',r.weight],['Рейсы',r.trips],['Расходы на партию',cfg.buyPrice?r.cost:'Нужна цена покупки'],['Чистая прибыль',r.valid?r.profit:'Нужны цены']];const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeff'+rows.map(row=>row.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}));a.download='Albion-transport-'+item.id+'.csv';a.click();URL.revokeObjectURL(a.href)};
 const craftRefresh=$('refresh').onclick,craftServerChange=$('server').onchange;
 $('refresh').onclick=()=>active?load(true):craftRefresh();$('server').onchange=()=>{if(!active){craftServerChange();return}state.server=$('server').value;draft();fill();save();schedule();$('art-routes').innerHTML='<tr><td colspan="7" class="empty">Сервер изменился. Рассчитайте маршруты заново.</td></tr>'};
 window.LuxuryUI={snapshot:()=>JSON.parse(JSON.stringify({item,config:cfg,result:lastResult,server:state.server})),captureDraft:()=>JSON.parse(JSON.stringify(state)),restoreDraft(d){Object.assign(state,JSON.parse(JSON.stringify(d)),{server:$('server').value});item=A.find(r=>r.id===state.selected);if(!item)throw Error('Предмет роскоши отсутствует.');draft();$('art-category').value=state.category;products();fill();render();schedule();},setServer(server){state.server=server;},activate(){if(active)return;active=true;craftServer=$('server').value;$('server').value=state.server;$('craft-content').hidden=true;panel.hidden=false;$('title').textContent='Перевозка роскоши';$('subtitle').textContent='Купить в одном городе, продать в другом — с учётом всех расходов.';document.querySelectorAll('button[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode==='luxury'));item=A.find(r=>r.id===state.selected)||A[0];draft();$('art-category').value=state.category;products();fill();render();schedule()},deactivate(){if(!active)return;active=false;clearTimeout(timer);sequence++;controller?.abort();loading=false;panel.hidden=true;$('craft-content').hidden=false;$('server').value=craftServer;$('refresh').disabled=false;$('refresh').textContent='↻ Обновить цены'}};
